package net.minecraft.client.multiplayer;import java.util.*;import net.minecraft.world.entity.Entity;import net.minecraft.core.BlockPos; public class ClientLevel {public final Map<Integer,Entity> entities=new LinkedHashMap<>();public boolean chunks=true;public final Set<Long> unavailableChunks=new HashSet<>();public int unavailableQueries;public Runnable onChunkQuery;public long time=47;public Entity getEntity(int id){return entities.get(id);}public boolean hasChunkAt(BlockPos p){Runnable callback=onChunkQuery;onChunkQuery=null;if(callback!=null)callback.run();boolean missing=unavailableChunks.contains(((long)Math.floorDiv(p.x(),16)<<32)^(Math.floorDiv(p.z(),16)&0xffffffffL));if(missing)unavailableQueries++;return chunks&&!missing;}public long getGameTime(){return time;}}
